import React, { useEffect, useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Save, Loader, UserPlus } from 'lucide-react';
import { useMutation } from '@tanstack/react-query';
import toast from 'react-hot-toast';
import salesRepService from '../../services/salesRepService';
import ValidatedInput from '../../components/forms/ValidatedInput';

const salesRepSchema = z.object({
    firstName: z.string().min(2, 'First name is required'),
    lastName: z.string().min(2, 'Last name is required'),
    email: z.string().email('Valid email is required'),
    phone: z.string().optional(),
    commissionStructure: z.enum(['commission_only', 'salary_only', 'salary_plus_commission']).optional(),
    baseSalary: z.string().optional().transform(val => val ? Number(val) : 0),
    commissionPercentage: z.string().optional().transform(val => val ? Number(val) : 0)
});

const SalesRepFormModal = ({ isOpen, onClose, editingRep, onSuccess }) => {
    const [commissionType, setCommissionType] = useState('');
    const isEditing = !!editingRep;

    const { register, handleSubmit, watch, reset, formState: { errors } } = useForm({
        resolver: zodResolver(salesRepSchema),
        defaultValues: {
            firstName: '',
            lastName: '',
            email: '',
            phone: '',
            commissionStructure: '',
            baseSalary: '',
            commissionPercentage: ''
        }
    });

    useEffect(() => {
        if (editingRep) {
            reset({
                firstName: editingRep.firstName || '',
                lastName: editingRep.lastName || '',
                email: editingRep.email || '',
                phone: editingRep.phone || '',
                commissionStructure: editingRep.commission?.structure || '',
                baseSalary: editingRep.commission?.baseSalary?.toString() || '',
                commissionPercentage: editingRep.commission?.commissionPercentage?.toString() || ''
            });
            setCommissionType(editingRep.commission?.structure || '');
        } else {
            reset({
                firstName: '',
                lastName: '',
                email: '',
                phone: '',
                commissionStructure: '',
                baseSalary: '',
                commissionPercentage: ''
            });
            setCommissionType('');
        }
    }, [editingRep, reset]);

    const mutation = useMutation({
        mutationFn: (data) => {
            const payload = {
                ...data,
                baseSalary: data.commissionStructure ? parseFloat(data.baseSalary) || 0 : undefined,
                commissionPercentage: data.commissionStructure ? parseFloat(data.commissionPercentage) || 0 : undefined
            };

            return isEditing
                ? salesRepService.updateSalesRep(editingRep.id, payload)
                : salesRepService.createSalesRep(payload);
        },
        onSuccess: (data) => {
            toast.success(isEditing ? 'Sales rep updated' : 'Sales rep created successfully');
            onSuccess(data.data || data);
        },
        onError: (error) => {
            toast.error(error.response?.data?.message || 'Operation failed');
        }
    });

    const watchCommissionStructure = watch('commissionStructure');

    return (
        <AnimatePresence>
            {isOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="fixed inset-0 bg-black/50 backdrop-blur-sm"
                        onClick={onClose}
                    />

                    <motion.div
                        initial={{ opacity: 0, scale: 0.95, y: 20 }}
                        animate={{ opacity: 1, scale: 1, y: 0 }}
                        exit={{ opacity: 0, scale: 0.95, y: 20 }}
                        className="relative bg-white dark:bg-gray-800 rounded-2xl shadow-xl w-full max-w-lg max-h-[90vh] overflow-y-auto"
                    >
                        {/* Header */}
                        <div className="flex items-center justify-between p-6 border-b border-gray-200 dark:border-gray-700">
                            <div className="flex items-center gap-2">
                                <UserPlus className="h-5 w-5 text-indigo-600" />
                                <h2 className="text-xl font-bold text-gray-900 dark:text-white">
                                    {isEditing ? 'Edit Sales Representative' : 'Add Sales Representative'}
                                </h2>
                            </div>
                            <button
                                onClick={onClose}
                                className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors"
                            >
                                <X className="h-5 w-5 text-gray-500" />
                            </button>
                        </div>

                        {/* Form */}
                        <form onSubmit={handleSubmit((data) => mutation.mutate(data))} className="p-6 space-y-4">
                            <div className="grid grid-cols-2 gap-4">
                                <ValidatedInput
                                    label="First Name"
                                    name="firstName"
                                    required
                                    error={errors.firstName?.message}
                                    {...register('firstName')}
                                />
                                <ValidatedInput
                                    label="Last Name"
                                    name="lastName"
                                    required
                                    error={errors.lastName?.message}
                                    {...register('lastName')}
                                />
                            </div>

                            <ValidatedInput
                                label="Email Address"
                                name="email"
                                type="email"
                                required
                                error={errors.email?.message}
                                {...register('email')}
                            />

                            <ValidatedInput
                                label="Phone Number"
                                name="phone"
                                type="tel"
                                placeholder="+234..."
                                error={errors.phone?.message}
                                {...register('phone')}
                            />

                            {!isEditing && (
                                <div className="p-4 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 rounded-lg">
                                    <p className="text-sm text-amber-800 dark:text-amber-400">
                                        A secure password will be automatically generated.
                                        Make sure to copy and share it securely with the sales rep.
                                    </p>
                                </div>
                            )}

                            {/* Commission Structure */}
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                                    Commission Structure (Optional)
                                </label>
                                <select
                                    {...register('commissionStructure')}
                                    onChange={(e) => {
                                        register('commissionStructure').onChange(e);
                                        setCommissionType(e.target.value);
                                    }}
                                    className="block w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-indigo-500"
                                >
                                    <option value="">No commission set</option>
                                    <option value="commission_only">Commission Only</option>
                                    <option value="salary_only">Salary Only</option>
                                    <option value="salary_plus_commission">Salary + Commission</option>
                                </select>
                            </div>

                            {/* Dynamic Commission Fields */}
                            <AnimatePresence>
                                {(commissionType === 'salary_only' || commissionType === 'salary_plus_commission') && (
                                    <motion.div
                                        initial={{ opacity: 0, height: 0 }}
                                        animate={{ opacity: 1, height: 'auto' }}
                                        exit={{ opacity: 0, height: 0 }}
                                    >
                                        <ValidatedInput
                                            label="Base Salary ($/month)"
                                            name="baseSalary"
                                            type="number"
                                            step="0.01"
                                            required
                                            error={errors.baseSalary?.message}
                                            {...register('baseSalary')}
                                        />
                                    </motion.div>
                                )}

                                {(commissionType === 'commission_only' || commissionType === 'salary_plus_commission') && (
                                    <motion.div
                                        initial={{ opacity: 0, height: 0 }}
                                        animate={{ opacity: 1, height: 'auto' }}
                                        exit={{ opacity: 0, height: 0 }}
                                    >
                                        <ValidatedInput
                                            label="Commission Percentage (%)"
                                            name="commissionPercentage"
                                            type="number"
                                            step="0.1"
                                            required
                                            error={errors.commissionPercentage?.message}
                                            {...register('commissionPercentage')}
                                        />
                                    </motion.div>
                                )}
                            </AnimatePresence>

                            {/* Actions */}
                            <div className="flex items-center justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
                                <button
                                    type="button"
                                    onClick={onClose}
                                    className="px-4 py-2 text-sm font-medium text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors"
                                >
                                    Cancel
                                </button>

                                <button
                                    type="submit"
                                    disabled={mutation.isLoading}
                                    className="flex items-center gap-2 px-6 py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg font-medium transition-colors disabled:opacity-50"
                                >
                                    {mutation.isLoading ? (
                                        <>
                                            <Loader className="h-4 w-4 animate-spin" />
                                            Saving...
                                        </>
                                    ) : (
                                        <>
                                            <Save className="h-4 w-4" />
                                            {isEditing ? 'Update' : 'Create'} Sales Rep
                                        </>
                                    )}
                                </button>
                            </div>
                        </form>
                    </motion.div>
                </div>
            )}
        </AnimatePresence>
    );
};

export default SalesRepFormModal;
